#include <stdio.h>
#include <stdlib.h>
int main(void) {
    int *p = malloc(3 * sizeof(int));
    if (p == NULL) return 1;
    p[0] = 10; p[1] = 20; p[2] = 30;
    printf("%d\n", p[0] + p[1] + p[2]);
    free(p);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
int main(void) {
    int *p = calloc(5, sizeof(int));
    if (p == NULL) return 1;
    int s = 0;
    for (int i = 0; i < 5; i++) s += p[i];
    printf("%d\n", s);
    free(p);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
int main(void) {
    int *p = malloc(2 * sizeof(int));
    if (p == NULL) return 1;
    p[0] = 5; p[1] = 10;
    int *tmp = realloc(p, 4 * sizeof(int));
    if (tmp == NULL) { free(p); return 1; }
    p = tmp;
    p[2] = 15; p[3] = 20;
    printf("%d\n", p[0] + p[1] + p[2] + p[3]);
    free(p);
    return 0;
}

