#include <stdio.h>
#include <stdlib.h>
int main(void) {
    int *p = malloc(2 * sizeof(int));
    if (p == NULL) return 1;
    p[0] = 1; p[1] = 2;
    int *tmp = realloc(p, 4 * sizeof(int));
    if (tmp == NULL) { free(p); return 1; }
    p = tmp;
    p[2] = p[0] + p[1];
    p[3] = p[2] + p[1];
    printf("%d %d %d %d\n", p[0], p[1], p[2], p[3]);
    free(p);
    return 0;
}

