#include <stdio.h>
#include <stdlib.h>
int main(void) {
    int n = 4;
    int *p = malloc((size_t)n * sizeof(int));
    if (p == NULL) return 1;
    for (int i = 0; i < n; i++) p[i] = (i + 1) * 10;
    int s = 0;
    for (int i = 0; i < n; i++) s += p[i];
    free(p);
    printf("%d\n", s);
    return 0;
}
